%[text] # Peak Search in FRFT Domain
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## Input Signal
% Signal
%fs = 1.1*(2*10.8e3 + 5e3);
fs = 50e3;
T  = 0.10;
%t  =  linspace(-T/2,T/2,fs*T);
t  =  linspace(-T,T,fs*T);
B  = fs/2;
k  = B/(T);
f0 = 0;
A  = 100;
s1_signal =  A*exp(1i * 2*pi * (f0.*t + 0.5*k.*t.^2));
padsize = ceil((1-T)*fs/2);
s1 = [zeros(1,padsize), s1_signal, zeros(1,padsize)];
t  = [-T/2 - padsize/fs: 1/fs : T/2 + padsize/fs - 1/fs];

figure %[output:62a90df4]
hold on %[output:62a90df4]
plot(t,real(s1)) %[output:62a90df4]
title("Chirp Signal") %[output:62a90df4]
hold off %[output:62a90df4]
%%
%[text] ## Windowing
% Assume that signal runs from -T/2 -> +T/2
% Therefore no zeros, just cos term
function out = hamming(gamma,sig)
    window = gamma+(1-gamma)*cos(2*pi* linspace( -1/2,+1/2,length(sig) ) );
    out = window.*sig;
end

figure %[output:64561e42]
hold on %[output:64561e42]
plot(t,real(s1),t,imag(s1)); %[output:64561e42]
title("Chirp Signal Windowed") %[output:64561e42]
hold off %[output:64561e42]
%[text] ## Adding Comms Signal
rrc_filter_tx = comm.RaisedCosineTransmitFilter(RolloffFactor=0.3, ...
        Shape='Normal', ...
        FilterSpanInSymbols=10, ...
        OutputSamplesPerSymbol=20);
rrc_filter_tx.Gain = 1/sum(rrc_filter_tx.coeffs.Numerator);



rng(1) % Set seed for repeatability
s2_bits = round(rand(1,floor((length(t)*(1/fs))*2500)));
%s2_bits = zeros(1,length(t)/270);

%s2_bits(1:2:end) = half(1);
%s2_signal = 2*(s2_bits-0.5); % polar nrz
s2_signal = pskmod(s2_bits,2,0,PlotConstellation=true); %[output:47ac133e]
%s2_signal = fskmod(s2_bits,2,0.5*fs/2,ceil(length(t) / length(s2_bits)),fs);


%s2 = s2_signal;
s2 = rrc_filter_tx(s2_signal);
s2 = s2(:)';
max(s2) %[output:891b28ef]
figure %[output:64534958]
hold on %[output:64534958]
plot(real(s2)) %[output:64534958]
plot(imag(s2)) %[output:64534958]
xlim() %[output:704842a4]
hold off %[output:64534958]
% Shift to IF and low pass
fc = single(15e3);
s2 = s2(1:length(t)).*sin(2*pi*fc*t);

s2 = bandpass(single(s2),[fc - 2500, fc+2500],fs) %[output:6e5a0411]
% Rescale to +1/-1
s2 = s2.* (1/max(abs(s2)));



max(s2) %[output:31b63153]

%s2 = awgn(s2,20);



max(s2) %[output:44642331]

s = 1*s1 + s2;

%s = [zeros(1,padsize), s, zeros(1,padsize)];
%t = [-T/2 - padsize/fs: 1/fs : T/2 + padsize/fs - 1/fs];

%s = hamming(0.54,s);

An = 0.01; % 20 dB SNR
sn = An*randn(1,length(s)) %[output:13cd8d4e]

s = s + sn;

s = single(s) %[output:7f427e79]

figure %[output:7c4df6c9]
plot(real(s)) %[output:7c4df6c9]
hold on %[output:7c4df6c9]
plot(imag(s)) %[output:7c4df6c9]
hold off %[output:7c4df6c9]
%[text] fourier domain:
fft_n_points = length(s);
s2_bb_fft = fft(s2_signal,fft_n_points);
s2_fc_fft = fft(s2,       fft_n_points);
s1_fft    = fft(s1,       fft_n_points);
F = linspace(0,1,fft_n_points/2).*(fs/2);

figure %[output:7931db9f]
subplot(3,1,1) %[output:7931db9f]
plot(F,10*log10(abs(s2_bb_fft(1:fft_n_points/2)).^2)); %[output:7931db9f]
title("Comms Signal @ Baseband") %[output:7931db9f]

subplot(3,1,2) %[output:7931db9f]
plot(F,10*log10(abs(s2_fc_fft(1:fft_n_points/2)).^2)); %[output:7931db9f]
title("Comms Signal @ IF") %[output:7931db9f]

subplot(3,1,3) %[output:7931db9f]
plot(F,10*log10(abs(s1_fft(1:fft_n_points/2)+eps).^2)); %[output:7931db9f]
title("Radar Signal") %[output:7931db9f]

sgtitle("FFT of signals") %[output:7931db9f]
%%
%[text] Let's have a look at it in frft domain:
p = 0: 1 / 400 : 2;

s_frft = zeros(length(p),length(s));

for i = 1:length(p)
    s_frft(i,:) = frft(s,p(i));
end

s_frft_sqmag = abs(s_frft).^2;

fig = figure();  %[output:19859117]
fig.Position(3:4) = [1000, 500]; %[output:19859117]

subplot(2,1,1) %[output:19859117]
frft_plot = imagesc(p,0:length(s)-1,10*log10(s_frft_sqmag)); %[output:19859117]
xlabel('p') %[output:19859117]
ylabel(" u ") %[output:19859117]
zlabel("|X_\alpha (u)|^2") %[output:19859117]
colormap(gca,hot), colorbar %[output:19859117]
%Place datatip at peak value
[frft_maxval,frft_maxidx] = max(s_frft_sqmag,[],"all");
frft_maxtip = datatip(frft_plot,'DataIndex',frft_maxidx,'Location','southwest'); %[output:19859117]
frft_plot.DataTipTemplate.DataTipRows(end+1) = dataTipTextRow("Magnitude",s_frft_sqmag); %[output:19859117]

subplot(2,1,2) %[output:19859117]
plot(p,max(10*log10(s_frft_sqmag'))) %[output:19859117]
ylabel("max(|X_\alpha (u)|^2)") %[output:19859117]

hold on; %[output:19859117]
p_opt = p(mod(frft_maxidx,length(p))) %[output:4dd82b38]
xline(p_opt, 'r--', 'LineWidth', 1.5); %[output:19859117]
hold off; %[output:19859117]
%%
%[text] ## Algorithm
%[text] Basic Gradient ascent
%[text] For each iteration:
%[text] 1. Calculate FRFT
%[text] 2. Find max(frft(alpha))
%[text] 3.  \
%[text] Next iteration:
%[text] 1. Is current \> best? Y -\> current = best \
%[text]  
p_bounds = [0 2]; %[control:rangeslider:0a7a]{"position":[12,17]}

% One order lower than the difference in bounds.
p_step     = 10^(floor(log10(p_bounds(2)-p_bounds(1)))-1);

p_current  = p_bounds(2);
p_previous = 0;
frft_current = zeros(1,length(s));

max_steps = 50; %[control:editfield:37eb]{"position":[13,15]}
p_vals = zeros(1,max_steps);

[p_best, best_val] = find_frft_peak(s, max_steps, p_bounds, false) %[output:4f55df20] %[output:7a88cfb0]
%%
%[text] ## Comparing Comms Sig + Isolated
s_frft  = frft(s, p_best);
s1_frft = frft(s1,p_best);
s2_frft = frft(s2,p_best);


figure %[output:796a0e69]
hold on %[output:796a0e69]

subplot(4,1,1) %[output:796a0e69]
plot((abs(s_frft).^2)); %[output:796a0e69]
title("Combined Signal") %[output:796a0e69]

subplot(4,1,2) %[output:796a0e69]
plot((abs(s1_frft).^2)); %[output:796a0e69]
title("Chirp") %[output:796a0e69]

subplot(4,1,3) %[output:796a0e69]
plot((abs(s2_frft).^2)); %[output:796a0e69]
title("Comms Signal") %[output:796a0e69]
subplot(4,1,4) %[output:796a0e69]
plot((abs(s_frft).^2)); %[output:796a0e69]
ylim([0, 1.1*max((abs(s2_frft).^2))]) %[output:796a0e69]
title("Combined Signal scaled to comms") %[output:796a0e69]
%%
%[text] ## IFRFT Peak Suppression
% s_frft_sqmag = abs(s_frft).^2;
% s_frft_sqmag_sdev = std(s_frft_sqmag);
% 
% s_frft_cancelled = s2_frft - s_frft ;
% 
% figure
% hold on
% 
% subplot(4,1,1)
% plot(10*log10(abs(frft(s,p_best)).^2));
% title("Combined Signal")
% 
% subplot(4,1,2)
% plot(10*log10(abs(frft(s1,p_best)).^2));
% title("Chirp")
% 
% subplot(4,1,3)
% plot(10*log10(abs(frft(s2,p_best)).^2));
% title("Comms Signal")
% 
% subplot(4,1,4)
% plot(10*log10(abs(s_frft_cancelled.^2)));
% title("Error between combined and comms Signal")

%s_cancelled = frft(s_frft_cancelled,-p_best);


figure %[output:5a8386d0]
hold on %[output:5a8386d0]
subplot(4,1,1) %[output:5a8386d0]
hold on %[output:5a8386d0]
plot(t,real(s1),DisplayName="Real") %[output:5a8386d0]
plot(t,imag(s1),DisplayName="Imaginary") %[output:5a8386d0]
title("Chirp") %[output:5a8386d0]

subplot(4,1,2) %[output:5a8386d0]
hold on %[output:5a8386d0]
plot(t,real(s2),DisplayName="Real") %[output:5a8386d0]
plot(t,imag(s2),DisplayName="Imaginary") %[output:5a8386d0]
title("Comms Signal") %[output:5a8386d0]

subplot(4,1,3) %[output:5a8386d0]
hold on %[output:5a8386d0]
plot(t,real(s),DisplayName="Real") %[output:5a8386d0]
plot(t,imag(s),DisplayName="Imaginary") %[output:5a8386d0]
title("Combined Signal") %[output:5a8386d0]

subplot(4,1,4) %[output:5a8386d0]
hold on %[output:5a8386d0]
%plot(t,real(s_cancelled),DisplayName="Real")
%plot(t,imag(s_cancelled),DisplayName="Imaginary")
%title("Cancelled Signal")
%%
%[text] ## Windowing FRFT size
%[text] In implementation paper, they've provided timings for 100 iterations on 1024 bin size as 12.98ms for area optimised, and 5.22 for speed optimised.
%[text] Let's try this out on the signal components and create some 3d plots.
window_size = 1024; %[control:editfield:46fb]{"position":[15,19]}
max_steps   = 100; %[control:editfield:4c51]{"position":[15,18]}
window = zeros(1,window_size);
% Add overlap here?



% Combined Signal
n_windows_s = ceil(length(s)/window_size);
% 0 Pad to window size.
s_padded = [s, zeros(1,mod(length(s),window_size))];


frft_arr_s = zeros(window_size,n_windows_s);
s_windowed = zeros(window_size,n_windows_s);

for n = 0:n_windows_s-1
   window = s_padded(1+n*window_size:(n+1)*window_size);

    s_windowed(:,n+1) = window;
   p_best = find_frft_peak(window, max_steps, p_bounds, false);

   frft_arr_s(:,n+1) = frft(window,p_best);
end
%%
fig = figure();  %[output:7b814da0]
frft_surf_s = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(frft_arr_s))); %[output:7b814da0]
shading interp %[output:7b814da0]
view([344 61]) %[output:7b814da0]

colorbar %[output:7b814da0]

fig = figure();  %[output:564bfd37]
fft_surf_s = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(fft(s_windowed)))); %[output:564bfd37]
shading interp %[output:564bfd37]
view([344 61]) %[output:564bfd37]
colorbar %[output:564bfd37]
title("Windowed FFT") %[output:564bfd37]

fig = figure();  %[output:04375d6d]
frft_surf_s = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(half(frft_arr_s)))); %[output:04375d6d]
shading interp %[output:04375d6d]
view([344 61]) %[output:04375d6d]

colorbar %[output:04375d6d]
fig = figure();  %[output:8fce810f]
frft_surf_s = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(fft(half(s_windowed))))); %[output:8fce810f]
shading interp %[output:8fce810f]
view([344 61]) %[output:8fce810f]
colorbar %[output:8fce810f]
%%
%[text] ## Recovery w. Quantisation
%[text] ### Windowing the Signals
% 0 Pad to window size.
s1_padded = [s1, zeros(1,mod(length(s1),window_size))];
s2_padded = [s2, zeros(1,mod(length(s2),window_size))];

s1_windowed = zeros(window_size,n_windows_s);
s2_windowed = zeros(window_size,n_windows_s);

for n = 0:n_windows_s-1
   s1_window = s1_padded(1+n*window_size:(n+1)*window_size);
   s1_windowed(:,n+1) = s1_window;

   s2_window = s2_padded(1+n*window_size:(n+1)*window_size);
   s2_windowed(:,n+1) = s2_window;
end
%%
%[text] ### Quantizing to 14 bit ADC
%[text] 14 bits, 13 fractional for I and Q
%[text] Normalising by max of s, Using the optimal gain for each window of s, to assume optimal AGC
for n = 0:n_windows_s-1
    gain(n+1) = 1*max(abs(s_windowed(:,n+1)));
    
    adc_bits = 14;
    adc_frac = adc_bits - 1;

    s_windowed_sfix(:,n+1)  = fi(s_windowed(:,n+1) ./ gain(n+1),1,adc_bits,adc_frac);
    s1_windowed_sfix(:,n+1) = fi(s1_windowed(:,n+1) ./ gain(n+1),1,adc_bits,adc_frac);
    s2_windowed_sfix(:,n+1) = fi(s2_windowed(:,n+1) ./ gain(n+1),1,adc_bits,adc_frac);

end


for n = 0:n_windows_s-1
   s_window = s_windowed_sfix(1+n*window_size:(n+1)*window_size);
   s_window = double(hamming(0.9,s_window));
   p_best_arr(n+1) = find_frft_peak(double(s_window), max_steps, p_bounds, false);
   s_windowed_frft_sfix(:,n+1) = frft(s_window,p_best_arr(n+1));

   s1_window = s1_windowed_sfix(1+n*window_size:(n+1)*window_size);
   s1_window = double(hamming(0.5,s1_window));
   %p_best = find_frft_peak(double(s1_window), max_steps, p_bounds, false);
   s1_windowed_frft_sfix(:,n+1) = frft(s1_window,p_best_arr(n+1));

   s2_window = s2_windowed_sfix(1+n*window_size:(n+1)*window_size);
   s2_window = double(hamming(0.5,s2_window));
   %p_best = find_frft_peak(double(s2_window), max_steps, p_bounds, false);
   s2_windowed_frft_sfix(:,n+1) = frft(double(s2_window),p_best_arr(n+1));
end

%%
%[text] ### Plotting Windowed Signals
fig = figure();  %[output:42d92c8b]
frft_surf_s = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(s_windowed_frft_sfix))); %[output:42d92c8b]
shading interp %[output:42d92c8b]
view([344 61]) %[output:42d92c8b]
colorbar %[output:42d92c8b]
fig = figure();  %[output:4d98decf]
frft_surf_1 = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(s1_windowed_frft_sfix))); %[output:4d98decf]
shading interp %[output:4d98decf]
view([344 61]) %[output:4d98decf]
colorbar %[output:4d98decf]

fig = figure();  %[output:14b7c7a4]
frft_surf_s2 = surface(0:n_windows_s-1,0:window_size-1,10*log10(abs(s2_windowed_frft_sfix))); %[output:14b7c7a4]
shading interp %[output:14b7c7a4]
view([344 61]) %[output:14b7c7a4]
colorbar %[output:14b7c7a4]
%%
%[text] ### Converting back to time domain to see  the signal error / window
for n = 0:n_windows_s-1 %[output:group:08f12381]
   s_frft_window = s_windowed_frft_sfix(1+n*window_size:(n+1)*window_size);
   s_windowed_ifrft_sfix(:,n+1) = frft(s_frft_window,-p_best_arr(n+1));

   s1_frft_window = s1_windowed_frft_sfix(1+n*window_size:(n+1)*window_size);
   s1_windowed_ifrft_sfix(:,n+1) = frft(s1_frft_window,-p_best_arr(n+1));

   s2_frft_window = s2_windowed_frft_sfix(1+n*window_size:(n+1)*window_size);
   s2_windowed_ifrft_sfix(:,n+1) = frft(s2_frft_window,-p_best_arr(n+1));


   % Cancelling by zeroing everything in frft > threshold
   thresh = 0.5;
   s_frft_cancelled(:,n+1)  =  s_frft_window - (s_frft_window .* (abs(s_frft_window) > thresh)); %[output:3bcadee7]
   s1_frft_cancelled(:,n+1) = s1_frft_window - (s1_frft_window .* (abs(s1_frft_window) > thresh)); 
   s2_frft_cancelled(:,n+1) = s2_frft_window - (s2_frft_window .* (abs(s2_frft_window) > thresh));
   
   s_ifrft_cancelled(:,n+1)  = frft(s_frft_cancelled(:,n+1) ,-p_best_arr(n+1));
   s1_ifrft_cancelled(:,n+1) = frft(s1_frft_cancelled(:,n+1),-p_best_arr(n+1));
   s2_ifrft_cancelled(:,n+1) = frft(s2_frft_cancelled(:,n+1),-p_best_arr(n+1));
   


   % Rescale by gain(n)
   s_windowed_ifrft_sfix(:,n+1)  = s_windowed_ifrft_sfix(:,n+1) .* gain(n+1);
   s1_windowed_ifrft_sfix(:,n+1) = s1_windowed_ifrft_sfix(:,n+1) .* gain(n+1);
   s2_windowed_ifrft_sfix(:,n+1) = s2_windowed_ifrft_sfix(:,n+1) .* gain(n+1);

   s_windowed_sfix_descale(:,n+1)  = s_windowed_sfix(:,n+1) .* gain(n+1);
   s1_windowed_sfix_descale(:,n+1) = s1_windowed_sfix(:,n+1) .* gain(n+1);
   s2_windowed_sfix_descale(:,n+1) = s2_windowed_sfix(:,n+1) .* gain(n+1);

   s_ifrft_cancelled(:,n+1)   = s_ifrft_cancelled(:,n+1) .* gain(n+1);
   s1_ifrft_cancelled(:,n+1)  = s1_ifrft_cancelled(:,n+1) .* gain(n+1);
   s2_ifrft_cancelled(:,n+1)  = s2_ifrft_cancelled(:,n+1) .* gain(n+1);
end %[output:group:08f12381]

% MSE
s_ifrft_sfix_error = mean(abs((s_windowed - s_windowed_ifrft_sfix)).^2);
s1_ifrft_sfix_error = mean(abs((s1_windowed - s1_windowed_ifrft_sfix)).^2);
s2_ifrft_sfix_error = mean(abs((s2_windowed - s2_windowed_ifrft_sfix)).^2);

% MSE
s_sfix_error  = mean(abs((s_windowed  - s_windowed_sfix_descale)).^2);
s1_sfix_error = mean(abs((s1_windowed - s1_windowed_sfix_descale)).^2);
s2_sfix_error = mean(abs((s2_windowed - s2_windowed_sfix_descale)).^2);


figure
hold on
n = 0:n_windows_s-1;
subplot(3,1,1)
plot(n, 10*log10(double(s_sfix_error)), "DisplayName", "S" );
legend
subplot(3,1,2)
plot(n, 10*log10(double(s1_sfix_error)), "DisplayName", "S1" );
legend
subplot(3,1,3)
plot(n, 10*log10(double(s2_sfix_error)), "DisplayName", "S2" );

sgtitle("MSE of Quantized vs Unquantized Time Domain Signal")
ylabel("|e(n)|^2 (dB)")
xlabel("n")
legend
hold off

figure
hold on
n = 0:n_windows_s-1;
plot(n, 10*log10(s_ifrft_sfix_error), "DisplayName", "S" );
plot(n, 10*log10(s1_ifrft_sfix_error), "DisplayName", "S1" );
plot(n, 10*log10(s2_ifrft_sfix_error), "DisplayName", "S2" );
title("MSE of IFRFT vs Time Domain Signal")
subtitle("Quantized to 14 bit ADC")
ylabel("|e(n)|^2 (dB)")
xlabel("n")
legend
hold off
%%
%[text] ### Looking Specifically at where the chirp comes in 
for n = 20:26
    figure

    subplot(4,1,1)
    sgtitle("TD Plots | N="+num2str(n))
    plot(real(s_windowed_sfix(:,n+1)));
    title("Combined Comms & Interference (time)")
    hold on
    
    hold off
    
    subplot(4,1,2)
    plot(real(s2_windowed_sfix(:,n+1)));
    title("Comms Signal (time)")

    subplot(4,1,3)
    plot(abs(s_windowed_frft_sfix(:,n+1)));
    title("Combined Comms & Interference (FRFT)")
    

    subplot(4,1,4)
    plot( abs( frft( s2_windowed,p_best_arr(n+1) ) ) )
    title("Comms Signal (FRFT)")
    

end
%%
for n = 20:26
    
    s_sfix_double(:,n+1) = double(s_windowed_sfix(:,n+1)).*gain(n+1);
    s_error(:,n+1) = s_sfix_double(:,n+1) - s_windowed_ifrft_sfix(:,n+1);
    s_s2_error(:,n+1) = double(s2_windowed_sfix(:,n+1)) - s_windowed_ifrft_sfix(:,n+1);

    



    figure

    subplot(4,1,1)
    sgtitle("Cancelling | N="+num2str(n))
    plot(real(s2_windowed_sfix_descale(:,n+1)), "DisplayName","Comms");
    title("Comms Signal vs Cancelled Combined Signal (time), N=")
    hold on
    plot(real(s_ifrft_cancelled(:,n+1)),"-","DisplayName","Combined (cancelled)")
    hold off
    legend
    
    %subplot(5,1,2)
    %plot(10*log10(abs(s_error(:,n+1)).^2));
    %plot(10*log10(abs(s_s2_error(:,n+1)).^2));
    %title("IFRFT Squared Error")
    %legend

    subplot(4,1,2)
    plot(abs(s_windowed_frft_sfix(:,n+1)),"DisplayName","Before");
    hold on
    plot(abs(s_frft_cancelled(:,n+1)), "-"),"DisplayName","After";
    title("FRFT Before / After Thresholding")
    legend

    subplot(4,1,3)
    plot(real(s_sfix_double(:,n+1)),"DisplayName","Before");
    title("Combined before/after cancellation (Time)")
    hold on
    plot(real(s_ifrft_cancelled(:,n+1)),"-","DisplayName","After");
    hold off
    legend

    subplot(4,1,4)
    plot(abs(fft(s_ifrft_cancelled(:,n+1))),"DisplayName","Canceleld Combined")
    hold on
    plot(abs(fft(s2_windowed(:,n+1))), "DisplayName","Comms Signal")
    title("Cancelled vs Comms Signal (FFT)")
    legend
  

end
%%
%[text] ## Filtering, Downconversion & Decoding
%[text] First let's get the reference decoding of s2\_sfix to confirm we're not crazy.
% Receive RRC Filter
rrc_filter_rx = comm.RaisedCosineReceiveFilter(RolloffFactor=0.3, ...
        Shape='Normal', ...
        FilterSpanInSymbols=10, ...
        InputSamplesPerSymbol=20, ...
        DecimationFactor=20/2 ...
        );
rrc_filter_rx.Gain = 1%/sum(rrc_filter_rx.coeffs.Numerator);

% Symbol synch
% https://uk.mathworks.com/help/comm/ref/comm.symbolsynchronizer-system-object.html
symbolSync = comm.SymbolSynchronizer( ...
    "SamplesPerSymbol",20);

% Equalisation
% https://uk.mathworks.com/help/comm/ug/equalize-a-bspk-signal.html
lineq = comm.LinearEqualizer( ...
    NumTaps=64, ...
    StepSize=0.1, ...
    Constellation=complex([-1 1]), ...
    ReferenceTap=4);
training_symbols = s2_signal(1:100);


% for n= 0:size(s2_windowed_sfix,2)-1
% 
% s2_sfix_filtered(:,n+1) = bandpass(single(s2_windowed_sfix(:,n+1)),[fc - 2000, fc+2000],fs);
% s2_sfix_dc(:,n+1)       = s2_sfix_filtered(:,n+1).* [sin(pi*2*fc*((0:1023).*1/fs))]';
% s2_sfix_lp(:,n+1)       = lowpass(s2_sfix_dc(:,n+1),2000,fs);
% s2_sfix_rrc(:,n+1)      = rrc_filter_rx(s2_sfix_lp(:,n+1));
% s2_sfix_bits(:,n+1)     = pskdemod(s2_sfix_rrc(:,n+1) , 2);
% %s2_sfix_biterrors(:,n+1) = 

s2_sfix_vec  = single(s2_windowed_sfix(:)');
s2_sfix_filt = bandpass(single(s2_sfix_vec),[fc - 2500, fc+2500],fs);
s2_sfix_dc   = s2_sfix_filt .* [sin(pi*2*fc*((0:length(s2_sfix_filt)-1).*1/fs))];

s2_sfix_lp   = lowpass(s2_sfix_dc,2500,fs);
s2_sfix_rrc  = double(rrc_filter_rx(s2_sfix_lp));
% Normalise the power
s2_sfix_rrc = s2_sfix_rrc%.* (1/max(abs(s2_sfix_rrc)));
s2_sfix_sync = symbolSync(s2_sfix_rrc');
s2_sfix_eq = lineq(s2_sfix_sync,complex(double(training_symbols))');



s2_sfix_bits = pskdemod(s2_sfix_eq, 2);

% remove bits associated with filling the filter
s2_sfix_bits = s2_sfix_bits( length(s2_sfix_bits) - length(s2_bits) +1 : end)

% Use cross correlation to find the lag associated with the highest
% correlation

[bit_corr, lags] = xcorr(s2_bits,s2_sfix_bits');






fc = single(15e3);
s2 = s2(1:length(t)).*sin(2*pi*fc*t);

%s2 = 






%%
%[text] ## Parameter Estimation
S = sqrt(T/fs)
est_phi = pi/2 * p_best;
est_f0 = s_frft
